import React from 'react';

function ShowtimeScreen({ movie, showtimes, rooms, onSelectShowtime, onBack }) {
  const lichChieuCuaPhim = showtimes.filter(st => st.movie_id === movie.id);

  return (
    <div style={{ color: '#e2e8f0', minHeight: '80vh' }}>
      <button
        className="btn mb-4 fw-bold text-white border-0"
        style={{
          background: 'linear-gradient(135deg, #7c3aed 0%, #ec4899 100%)',
          boxShadow: '0 18px 30px rgba(124, 58, 237, 0.35)'
        }}
        onClick={onBack}
      >⬅ Quay lại trang chủ</button>

      <div
        className="card p-4 shadow-sm border-0"
        style={{
          background: 'rgba(15, 23, 42, 0.94)',
          border: '1px solid rgba(124, 58, 237, 0.22)',
          boxShadow: '0 28px 60px rgba(0, 0, 0, 0.30)'
        }}
      >
        <div className="d-flex justify-content-between align-items-start mb-3">
          <div>
            <h3 className="fw-bold mb-1" style={{ color: '#f9a8d4' }}>🎬 {movie.title}</h3>
            <p className="mb-0" style={{ color: '#cbd5e1' }}>Vui lòng chọn một suất chiếu phù hợp với thời gian của bạn:</p>
          </div>
          <div className="text-end small">
            <div className="fw-bold" style={{ color: '#fbbf24' }}>⭐ {movie.rating}</div>
            <div className="mt-1" style={{ color: '#94a3b8' }}>👁 {movie.viewers.toLocaleString()}</div>
          </div>
        </div>

        <div className="row">
          {lichChieuCuaPhim.length > 0 ? (
            lichChieuCuaPhim.map((st) => (
              <div className="col-sm-6 col-md-4 mb-3" key={st.id}>
                <button
                  className="btn p-3 w-100 text-start shadow-sm fw-bold"
                  style={{
                    border: '1px solid rgba(124, 58, 237, 0.35)',
                    backgroundColor: 'rgba(15, 23, 42, 0.88)',
                    color: '#e2e8f0',
                    minHeight: '160px'
                  }}
                  onClick={() => onSelectShowtime(st)}
                >
                  <div className="fs-6" style={{ color: '#94a3b8' }}>📅 Ngày: {st.show_date}</div>
                  <div className="fs-6" style={{ color: '#94a3b8' }}>🏟 Phòng: {rooms.find(r => r.id === st.room_id)?.name || 'Chưa xác định'}</div>
                  <div className="fs-3 my-1" style={{ color: '#a78bfa' }}>⏰ Giờ: {st.show_time}</div>
                  <hr className="my-2" style={{ borderColor: 'rgba(148, 163, 184, 0.18)' }}/>
                  <div className="small" style={{ color: '#cbd5e1' }}>Giá vé: {st.ticket_price.toLocaleString()}đ</div>
                </button>
              </div>
            ))
          ) : (
            <div className="col-12 text-center py-4" style={{ color: '#94a3b8' }}>Hiện tại phim này chưa có lịch chiếu mới.</div>
          )}
        </div>
      </div>
    </div>
  );
}

export default ShowtimeScreen;
